//! The validated authorization capability and the staleness rules behind it.

use std::collections::BTreeMap;
use std::path::Path;

use callisto_model::vcs::access::{GitCommitTrustEvidence, GitHeadDisposition};
use callisto_model::{
    AbsentProof, ApplyPermit, CommandRunner, ExactEvidence, ExecutionTrustProfileV1, ProviderObservationV1,
    ReleaseDecisionV1, ReleaseIntentError, ReleaseIntentV1, ReleaseOperationId, SourceIdentity,
};

use crate::error::ReleasePreconditionRequirement;
use crate::{DependencyResolver, GraphError, ProjectLocator, Workspace};

use super::binding::{recheck_git_remote, PreparedGitRemote};
use super::derive::{
    artifact_policy_from_intent, derive_release_intent, derive_release_intent_with_prepared, ArtifactBuildPolicy,
    GitRemoteRequirement,
};
use super::provider::{
    provider_for, EffectAuthorization, PreparedOperation, ProviderContext, ProviderRequest, PypiFileSets,
    ReleasePreflight, ReleaseProviderSet,
};
use super::release_artifacts::VerifiedArtifactManifest;
use super::StaleReason;

/// Graph-private inputs prepared from the same fresh observation as an intent.
/// Retaining them in the capability prevents a validated public intent being
/// paired with new inputs.
#[derive(Debug)]
pub(crate) struct PreparedReleaseInputs {
    pub(crate) root: std::path::PathBuf,
    pub(crate) source: SourceIdentity,
    trust: GitCommitTrustEvidence,
    git_remote: Option<PreparedGitRemote>,
    pub(crate) operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
}

/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
/// workspace observation. It is intentionally neither cloneable nor serializable.
pub struct ValidatedReleaseIntent<'a> {
    intent: ReleaseIntentV1,
    prepared: PreparedReleaseInputs,
    runner: &'a dyn CommandRunner,
    file_sets: PypiFileSets,
}

impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ValidatedReleaseIntent")
            .field("intent", &self.intent)
            .finish_non_exhaustive()
    }
}

impl ValidatedReleaseIntent<'_> {
    pub fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }

    #[cfg(test)]
    pub(crate) fn prepared(&self) -> &PreparedReleaseInputs {
        &self.prepared
    }

    fn context(&self) -> ProviderContext<'_> {
        ProviderContext::new(&self.prepared.root, self.runner, self.prepared.git_remote.as_ref())
            .with_file_sets(&self.file_sets)
    }

    /// Builds every Python publish of the intent into `outdir` and returns the packages built.
    ///
    /// This is the credential-free build job's work: the executing job later uploads these exact files.
    pub fn build_python_distributions(&self, outdir: &Path) -> Result<Vec<String>, GraphError> {
        let context = self.context();
        let mut built = Vec::new();
        for (id, prepared) in &self.prepared.operations {
            let PreparedOperation::RegistryPublish(operation) = prepared else {
                continue;
            };
            if id.package.ecosystem() != callisto_model::Ecosystem::Pypi {
                continue;
            }
            super::provider::build_python_into(&context, operation, outdir)?;
            built.push(operation.package_name.clone());
        }
        Ok(built)
    }

    fn prepared_operation(&self, id: &ReleaseOperationId) -> Result<&PreparedOperation, GraphError> {
        self.prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("no prepared operation for `{id:?}`"),
            })
    }
}

/// The production provider set: every operation is routed to the adapter
/// prepared for it during fresh validation, so no caller-supplied path,
/// endpoint, tag, package name, or version can reach a provider.
impl ReleaseProviderSet for ValidatedReleaseIntent<'_> {
    fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }

    fn recheck_trust(&self) -> Result<(), GraphError> {
        let evidence =
            callisto_model::vcs::GitAccess::new(&self.prepared.root, self.runner).observe_git_commit_trust()?;
        if evidence.identity() != self.prepared.trust.identity() || source_from_trust(&evidence) != self.prepared.source
        {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::trust_evidence_changed(),
            });
        }
        // An unreadable remote propagates as itself; only a readable, different remote is "stale".
        if let Some(expected) = self.prepared.git_remote.as_ref() {
            recheck_git_remote(&self.prepared.root, self.runner, expected)?;
        }
        Ok(())
    }

    fn preflight(
        &self,
        id: &ReleaseOperationId,
        artifacts: Option<&VerifiedArtifactManifest<'_>>,
    ) -> Result<ReleasePreflight, GraphError> {
        let operation = self.prepared_operation(id)?;
        provider_for(operation).preflight(
            &self.context(),
            &ProviderRequest {
                id,
                operation,
                artifacts,
            },
        )
    }

            sealed: true,
            uploaded: Mutex::new(Vec::new()),
        })
    }

    /// Re-hashes the files about to be uploaded: a sealed file changed after verification must not reach the index.
    pub(super) fn recheck(&self, files: &[&BuiltFile]) -> Result<(), GraphError> {
        if !self.sealed {
            return Ok(());
        }
        for file in files {
            let metadata = std::fs::symlink_metadata(&file.path).map_err(io_error)?;
            if !metadata.is_file() || file_sha256(&file.path)? != file.sha256 {
                return Err(GraphError::ArtifactBytesMismatch {
                    path: file.path.clone(),
                });
            }
        }
        Ok(())
    }

    pub(super) fn mark_uploaded(&self, files: &[&BuiltFile]) {
        let mut uploaded = self.uploaded.lock().expect("uploaded list is never poisoned");
        uploaded.extend(files.iter().map(|file| file.filename.clone()));
    }

    fn uploaded(&self) -> Vec<String> {
        self.uploaded.lock().expect("uploaded list is never poisoned").clone()
    }
}

/// The sealed file set of every Python publish in `intent`, from the build output in `dir`.
pub(crate) fn seal_distributions(
    intent: &callisto_model::ReleaseIntentV1,
    dir: &Path,
) -> Result<Vec<callisto_model::DistributionSetV1>, GraphError> {
    let mut sets = Vec::new();
    for (package, rendered) in callisto_model::python_publishes(intent) {
        let version = intent
            .operations
            .iter()
            .map(|operation| operation.id())
            .find(|id| id.package == *package && id.version.render() == rendered)
            .map(|id| id.version.clone())
            .expect("a Python publish listed from the intent is in the intent");
        let files = inventory(dir, package.name(), &version)?
            .into_iter()
            .map(|file| {
                let byte_length = std::fs::metadata(&file.path).map_err(io_error)?.len();
                let digest = callisto_model::ArtifactDigest::parse(&file.sha256)
                    .expect("a SHA-256 hex digest is a canonical artifact digest");
                Ok(callisto_model::DistributionFileV1 {
                    filename: file.filename,
                    digest,
                    byte_length,
                })
            })
            .collect::<Result<Vec<_>, GraphError>>()?;
        sets.push(callisto_model::DistributionSetV1 {
            package: package.clone(),
            version: rendered,
            files,
        });
    }
    Ok(sets)
}

/// How the index's files for a release differ from the files a build declared.
#[derive(Debug, Default, PartialEq, Eq)]
pub(super) struct Comparison<'a> {
    /// Declared files the index lacks.
    pub(super) missing: Vec<&'a str>,
    /// Declared files the index holds yanked.
    pub(super) yanked: Vec<&'a str>,
    /// Files whose index digest differs from the local file.
    pub(super) differing: Vec<&'a str>,
    /// Files the index holds for this release that no build declared.
    pub(super) extras: Vec<&'a str>,
}

impl Comparison<'_> {
    /// Whether every declared file is on the index, with nothing to flag about it.
    pub(super) fn is_complete(&self) -> bool {
        self.missing.is_empty() && self.yanked.is_empty() && self.differing.is_empty()
    }
}

/// Presence is by filename. A sealed set compares every digest; otherwise only files this run uploaded, as a
/// rebuild need not match an earlier attempt.
pub(super) fn compare<'a>(set: &'a BuiltSet, remote: &'a [PypiSimpleFile]) -> Comparison<'a> {
    let uploaded = set.uploaded();
    let mut comparison = Comparison::default();
    for file in &set.files {
        match remote.iter().find(|candidate| candidate.filename == file.filename) {
            None => comparison.missing.push(&file.filename),
            Some(held) if held.is_yanked() => comparison.yanked.push(&file.filename),
            Some(held) => {
                let unconfirmed = if set.sealed {
                    held.sha256() != Some(file.sha256.as_str())
                } else {
                    uploaded.contains(&file.filename) && held.sha256().is_some_and(|digest| digest != file.sha256)
}

/// Refuses to report success until every operation has an observed terminal
/// success state.
fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
    let count = intent
        .operations
        .iter()
        .filter(|operation| {
            !state
                .operation_state(operation.id())
                .is_some_and(OperationState::is_success)
        })
        .count();
    if count == 0 {
        Ok(())
    } else {
        Err(GraphError::ReleaseIncomplete { count })
    }
}

/// Requires the verification capability whenever `intent` declares compiled
/// binary slots. Its private constructor already proved both manifest binding
/// and local byte/attestation identity.
fn require_verified_artifact_manifest(
    intent: &ReleaseIntentV1,
    artifacts: Option<&VerifiedArtifactManifest<'_>>,
) -> Result<(), GraphError> {
    match (intent.artifact_slots.is_empty(), artifacts) {
        (true, None) => Ok(()),
        (true, Some(artifacts)) if !callisto_model::python_publishes(intent).is_empty() => {
            require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest()))
        }
        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
            detail: "verified artifact manifest supplied for a release intent with nothing to seal".to_owned(),
        }),
        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
        }),
    }
