    files.sort_by(|left, right| left.filename.cmp(&right.filename));
    for (present, missing) in [
        (files.iter().any(|file| is_pypi_wheel(&file.filename)), "wheel"),
        (files.iter().any(|file| is_pypi_sdist(&file.filename)), "sdist"),
