fn help_lists(help: &str, flag: &str) -> bool {
    let word = |c: char| c.is_ascii_alphanumeric() || c == '-' || c == '_';
    let mut spellings = vec![flag.to_owned()];
    if let Some(name) = flag.strip_prefix("--no-") {
