#![cfg(target_os = "linux")]

//! Real-registry e2e coverage. Linux only: CI installs the registries there.
//!
//! `release_forge_publish_e2e_tests.rs` and `durable_release_e2e_tests.rs`
//! cover npm and PyPI publish only against fake providers. This file adds a
//! real local Verdaccio registry to the mix: `callisto release execute`'s
//! actual npm provider adapter, real `npm`, real HTTP over loopback. The
//! fake-provider suites are unchanged and remain the fast, hermetic default.
//!
//! Registry routing goes entirely through npm's own `.npmrc` (a project-root
//! file, gitignored so it never dirties the release-trust worktree check),
//! never a callisto registry binding: `registry_endpoint::canonical_registry_url`
//! rejects non-https URLs with no loopback exception, by design, so a local `http://127.0.0.1` test
//! registry can never be configured as a `[registries]` entry. Leaving the
//! package unmatched by any `[registries]` override keeps
//! `PreparedRegistryBinding.endpoint` at `None`, which is also what makes
//! this reachable at all: both `npm view` (observation) and `npm publish`
//! omit `--registry` whenever `endpoint` is `None`, so npm resolves the
//! registry itself from `.npmrc` -- unlike PyPI's observation step, which
//! hardcodes the public simple index when `endpoint` is `None` (see the PyPI
//! note below).
//!
//! PyPI drives `registry_argv::pypi_build_argv` and `pypi_upload_argv` directly (the exact
//! production build and upload argv, including `--repository-url` for a
//! private index) rather than through `callisto release execute`: that CLI
//! path routes a registry through `PreparedRegistryBinding`, whose
//! `canonical_registry_url` rejects non-https with no loopback exception --
//! by design -- so a callisto
//! registry binding can never target a local `http://127.0.0.1` test index.
//! Calling those directly stays on the same side of that line
//! as the npm test above: real registry, real package-manager config
//! (`--repository-url`, not `.pypirc`), zero callisto-side registry binding.
//! The upload argv never carries `--skip-existing`, which twine 5 and newer refuses to run
//! at all against a non-warehouse repository URL (`UnsupportedConfiguration`).
//!
//! Cargo drives `registry_argv::cargo_publish_argv` directly against a real
//! local `cargo-http-registry`, for a third, different reason than PyPI's:
//! `cargo publish --registry <key>` and `cargo info --registry <key>` never
//! carry a URL at all, only the registry's *name* -- the URL lives entirely
//! in `.cargo/config.toml`, which callisto never writes. So the one
//! `PreparedRegistryBinding` requirement that would block this (an `https`
//! callisto-side binding) never applies: a `[registries]` entry with a
//! `kind` and no `url` leaves `endpoint` at `None` and the key still reaches
//! `cargo` as `--registry local-e2e`. Driving `cargo_publish_argv` directly
//! here (rather than through `callisto release execute`) keeps this test
//! independent of the git-remote scheme check (`https`/`ssh` only), which is
//! an orthogonal gate on the *release commit's* origin, not on the registry.
//! `cargo-http-registry` serves a git-protocol index (not sparse), so
//! `.cargo/config.toml` also needs `net.git-fetch-with-cli = true` --
//! libgit2's HTTP client rejects the server's dumb-protocol content type.

#[path = "common/release_harness.rs"]
mod release_harness;

use std::fs;
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};
fn npm_registry_release_fixture(package_name: &str) -> (tempfile::TempDir, String) {
    npm_release_fixture(&[(package_name, &[])])
}

/// The same fixture for several npm packages, each with the packages it depends on. Every package gets a minor bump.
fn npm_release_fixture(packages: &[(&str, &[&str])]) -> (tempfile::TempDir, String) {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    git(root, &["remote", "add", "origin", NPM_ORIGIN]);

    fs::write(root.join(".gitignore"), ".npmrc\n").unwrap();
    fs::write(
        root.join("package.json"),
        "{\n  \"name\": \"npm-registry-fixture-root\",\n  \"version\": \"0.0.0\",\n  \"private\": true,\n  \"workspaces\": [\"packages/*\"]\n}\n",
    )
    .unwrap();
    for (name, dependencies) in packages {
        let directory = root.join("packages").join(name.replace('/', "-"));
        fs::create_dir_all(&directory).unwrap();
        let dependencies = dependencies
            .iter()
            .map(|dependency| format!("\"{dependency}\": \"^0.1.0\""))
            .collect::<Vec<_>>()
            .join(", ");
        fs::write(
            directory.join("package.json"),
            format!(
                "{{\n  \"name\": \"{name}\",\n  \"version\": \"0.1.0\",\n  \"dependencies\": {{{dependencies}}}\n}}\n"
            ),
        )
        .unwrap();
    }
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "initial workspace"]);

    let init = callisto(root, &["init", "--yes", "--versioning", "independent"]);
    assert!(init.status.success(), "init failed: {}", stderr_of(&init));
    let config_path = root.join("callisto.toml");
    let mut config = fs::read_to_string(&config_path).unwrap();
    for (name, _) in packages {
        config.push_str(&format!(
            "\n[[package]]\nmatch = \"npm/{name}\"\npublish-to = [\"npm\"]\n"
        ));
    }
    fs::write(&config_path, config).unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "configure callisto"]);

    let mut add_args = vec!["add".to_owned()];
    for (name, _) in packages {
        add_args.push("--package".to_owned());
        add_args.push(format!("npm/{name}:minor"));
    }
    add_args.push("--summary".to_owned());
    add_args.push("Ship real-registry e2e coverage".to_owned());
    let add_args: Vec<&str> = add_args.iter().map(String::as_str).collect();
    let add = callisto(root, &add_args);
    assert!(add.status.success(), "add failed: {}", stderr_of(&add));
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "add release changeset"]);

    let version = callisto(root, &["version", "--emit-decision", DECISION_PATH]);
    assert!(version.status.success(), "version failed: {}", stderr_of(&version));

    for entry in fs::read_dir(root.join(".changeset")).unwrap() {
        let path = entry.unwrap().path();
        if path.file_name().is_some_and(|name| name != "README.md")
            && path.extension().is_some_and(|extension| extension == "md")
        {
            fs::remove_file(path).unwrap();
        }
    }
    git(root, &["add", "-A"]);
    git(root, &["commit", "-m", "release npm packages 0.2.0"]);
    let release_commit = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &release_commit]);
    (dir, release_commit)
}

/// A missing test tool skips on a developer machine but fails under CI, where the workflow installs every one of them:
/// a skip there would report as a pass and hide that nothing ran.
fn skip_missing(what: &str) {
    assert!(
        std::env::var_os("CI").is_none() || std::env::var_os("CALLISTO_ALLOW_MISSING_TOOLS").is_some(),
        "{what}; the CI workflow must install it"
                    "flag `{name}` is not allowed for `{tool} {}`: {line}",
                    words[..len].join(" ")
                ));
            }
        }
    }
}

/// Fake `cargo`/`gh`/`git` on a private PATH directory plus the env that
/// steers them.
pub struct Rig {
    pub bin: PathBuf,
    pub log: PathBuf,
    pub forge_marker: PathBuf,
    pub git_trace: PathBuf,
    pub cargo_calls: PathBuf,
    pub gh_calls: PathBuf,
    env: Vec<(String, String)>,
}

impl Rig {
    pub fn new(external: &Path, release_commit: &str) -> Self {
        use std::os::unix::fs::PermissionsExt;
        let bin = external.join("rig-bin");
        fs::create_dir_all(&bin).unwrap();
        for (name, body) in [("cargo", rig_cargo()), ("gh", rig_gh()), ("git", rig_git())] {
            fs::write(bin.join(name), body).unwrap();
            fs::set_permissions(bin.join(name), fs::Permissions::from_mode(0o755)).unwrap();
        }
        write_fixture_templates(&bin);
        let mut rig = Self {
            log: external.join("external-effects.log"),
            forge_marker: external.join("forge-release-created"),
            git_trace: external.join("git-commands.log"),
            cargo_calls: external.join("cargo-calls.log"),
            gh_calls: external.join("gh-calls.log"),
            bin,
            env: Vec::new(),
        };
        rig.set("CALLISTO_TEST_FORGE_COMMITISH", release_commit);
        rig
    }

    pub fn set(&mut self, key: &str, value: &str) -> &mut Self {
        self.env.retain(|(existing, _)| existing != key);
        self.env.push((key.to_owned(), value.to_owned()));
        self
    }

    /// `cargo publish` leaves `target/package/` in its working directory.
    pub fn real_cargo_target_dir(&mut self) -> &mut Self {
        self.set("CALLISTO_TEST_CARGO_TARGET", "1")
    }
    /// A release created without `--target` reports the default branch as `target_commitish`.
    pub fn forge_default_branch(&mut self, branch: &str) -> &mut Self {
        self.set("CALLISTO_TEST_FORGE_COMMITISH", branch)
    }
    /// `git push`/`ls-remote` are real git against a bare `file://` remote that replaces `remote_url` in their arguments.
    pub fn real_git_push(&mut self, bare: &Path, remote_url: &str) -> &mut Self {
        self.set("CALLISTO_TEST_PUSH", "real")
            .set("CALLISTO_TEST_BARE_REMOTE", &format!("file://{}", bare.display()))
            .set("CALLISTO_TEST_REMOTE_URL", remote_url)
    }
    pub fn failing_git_push(&mut self) -> &mut Self {
        self.set("CALLISTO_TEST_PUSH", "fail")
    }

    pub fn log_count(&self, needle: &str) -> usize {
        fs::read_to_string(&self.log)
            .unwrap_or_default()
            .matches(needle)
            .count()
    }
    pub fn cargo_calls(&self) -> Vec<(String, String)> {
        fs::read_to_string(&self.cargo_calls)
            .unwrap_or_default()
            .lines()
            .filter_map(|line| line.split_once('|'))
            .map(|(cwd, argv)| (cwd.to_owned(), argv.to_owned()))
            .collect()
    }
    pub fn gh_calls(&self) -> Vec<String> {
        fs::read_to_string(&self.gh_calls)
            .unwrap_or_default()
            .lines()
            .map(str::to_owned)
            .collect()
    }
}

pub fn bare_remote(dir: &Path) -> PathBuf {
    let bare = dir.join("remote.git");
    let output = Command::new(system_git())
        .args(["init", "--bare", "-b", "main"])
        .arg(&bare)
        .output()
        .unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    // Background auto-gc/maintenance can race the pushes this bare remote receives.
    for args in [["config", "gc.auto", "0"], ["config", "maintenance.auto", "false"]] {
        let output = Command::new(system_git())
            .args(args)
            .current_dir(&bare)
            .output()
            .unwrap();
        assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    }
    bare
}

/// Runs `callisto release execute` under the rig; `extra` are appended CLI arguments.
pub fn execute_rig(
    root: &Path,
    intent: &Path,
    receipt: &Path,
    rig: &Rig,
    forge_tag: &str,
    extra: &[&str],
    orchestration: Option<&str>,
) -> Output {
    execute_rig_in(root, root, intent, receipt, rig, forge_tag, extra, orchestration)
}

/// The same run with `--cwd` chosen separately from the fixture root.
#[allow(clippy::too_many_arguments)]
pub fn execute_rig_in(
    root: &Path,
    cwd: &Path,
    intent: &Path,
    receipt: &Path,
    rig: &Rig,
    forge_tag: &str,
    extra: &[&str],
    orchestration: Option<&str>,
) -> Output {
    let head = git(root, &["rev-parse", "HEAD"]);
    rig_command(root, cwd, rig, forge_tag)
        .args([
            "release",
            "execute",
            "--intent",
            intent.to_str().unwrap(),
            "--receipt",
            receipt.to_str().unwrap(),
            "--orchestration-revision",
            orchestration.unwrap_or(&head),
        ])
        .args(extra)
        .output()
        .expect("release execute should run")
}

/// A `callisto` command wired to the rig's fake providers, for any release subcommand.
pub fn rig_command(root: &Path, cwd: &Path, rig: &Rig, forge_tag: &str) -> Command {
    let path = format!("{}:{}", rig.bin.display(), std::env::var("PATH").unwrap());
    let mut command = Command::new(env!("CARGO_BIN_EXE_callisto"));
    command
        .args(["--format", "json", "--cwd", cwd.to_str().unwrap()])
