            ("NPM_TOKEN", &["npm", "pnpm", "yarn", "bun"]),
            ("NODE_AUTH_TOKEN", &["npm", "pnpm", "yarn", "bun"]),
            ("ACTIONS_ID_TOKEN_REQUEST_TOKEN", &["npm", "pnpm", "yarn", "bun"]),
            ("ACTIONS_ID_TOKEN_REQUEST_URL", &["npm", "pnpm", "yarn", "bun"]),
            ("CARGO_REGISTRY_TOKEN", &["cargo"]),
            ("GH_TOKEN", &["gh"]),
            ("GITHUB_TOKEN", &["gh"]),
            ("PYPI_TOKEN", &[]),
            ("CALLISTO_PUBLISH_NPM_CONFIG", &[]),
            ("TWINE_USERNAME", &[]),
            ("TWINE_PASSWORD", &[]),
        ];
        let tools = [
            "npm", "pnpm", "yarn", "bun", "cargo", "gh", "git", "curl", "uv", "twine", "python3", "env", "sh",
        ];
        assert_eq!(
            owners.len(),
            RELEASE_CREDENTIALS.len(),
            "every release credential needs an owner row"
        );
        for (credential, owning_tools) in owners {
            assert!(
                RELEASE_CREDENTIALS.contains(credential),
                "{credential} is not a release credential"
            );
        dir.path(),
        InitArgs::default(),
        true,
        vec![Answer::Confirm(true), Answer::Confirm(true)],
        false,
        &fake_ls_remote(env!("CARGO_PKG_VERSION")),
    );
    assert_eq!(run.result.unwrap(), std::process::ExitCode::SUCCESS);
    assert_eq!(run.prompter.prompts(), [WORKFLOW_PROMPT, WRITE_PROMPT]);
    assert_eq!(run.prompter.asked[0].1.as_deref(), Some("true"), "defaults to Y");
    let workflow = workflow_file(dir.path());
    assert!(
        workflow.contains(&format!(
            "uses: orin-dx/callisto/.github/actions/callisto-action@{FAKE_COMMIT} # callisto@{}",
            env!("CARGO_PKG_VERSION")
        )),
        "{workflow}"
    );
    assert!(workflow.contains("with: {mode: version-pr, branch: \"main\"}"));
    assert!(workflow.contains("with: {mode: release}"));
    assert!(
        run.out.contains(".github/workflows/callisto-release.yml:"),
        "{}",
        run.out
    );
}

